// SPDX-License-Identifier: MIT
// Provenance: original
//
// HypotCases writes hypot_data_test.go: the results of Java's
// StrictMath.hypot on pairs of special and boundary values, and the SHA-256
// of its results on pseudo-random pairs drawn as gen.draw of
// strictmath_test.go draws them. It fails when Math.hypot, which RoleLabels
// calls, differs from StrictMath.hypot. From the repository root:
//
//   javac -d /tmp/hypot-cases internal/jmath/testdata/HypotCases.java
//   java -cp /tmp/hypot-cases HypotCases > internal/jmath/hypot_data_test.go

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;

public class HypotCases {

	static final long CANONICAL_NAN = 0x7ff8000000000000L;

	// Special values: every pair of them is a case.
	static final long[] SPECIALS = { 0L, 0x8000000000000000L, CANONICAL_NAN, 0x7ff0000000000000L,
			0xfff0000000000000L, 0x3ff0000000000000L, 0xbff0000000000000L, 0x4008000000000000L,
			0x4010000000000000L, 1L, 0x8000000000000001L, 0x000fffffffffffffL, 0x0010000000000000L,
			0x7fefffffffffffffL, 0xffefffffffffffffL, 0x3c30000000000000L, 0x3c20000000000000L };

	// Pairs on the boundaries of the method: the ratio 2**60, the scaling
	// thresholds 2**500 and 2**-500, the two branches (a > 2b), equal high
	// words, subnormals.
	static final long[][] PAIRS = { //
			{ 0x3ff0000000000000L, 0x3c30000000000000L }, { 0x3ff0000000000000L, 0x3c2fffffffffffffL },
			{ 0x3ff0000000000000L, 0x3c30000000000001L }, { 0x3ff0000000000001L, 0x3c30000000000000L },
			{ 0x5f30000000000000L, 0x5f30000000000000L }, { 0x5f30000000000001L, 0x5f30000000000000L },
			{ 0x5f300000ffffffffL, 0x5f2fffffffffffffL }, { 0x5f30000100000000L, 0x5f30000100000000L },
			{ 0x5f30000100000000L, 0x5b70000100000000L }, { 0x7fefffffffffffffL, 0x7fefffffffffffffL },
			{ 0x7fefffffffffffffL, 0x7fe0000000000000L }, { 0x20b0000000000000L, 0x20b0000000000000L },
			{ 0x20afffffffffffffL, 0x20afffffffffffffL }, { 0x24700000ffffffffL, 0x20afffffffffffffL },
			{ 0x20b0000000000000L, 0x0010000000000000L }, { 0x0010000000000000L, 0x000fffffffffffffL },
			{ 0x000fffffffffffffL, 0x000fffffffffffffL }, { 0x0000000000000003L, 0x0000000000000004L },
			{ 0x0000000000000001L, 0x0000000000000001L }, { 0x0010000000000001L, 0x0000000000000001L },
			{ 0x3ff0000000000001L, 0x3ff0000000000002L }, { 0x3ff0000000000002L, 0x3ff0000000000001L },
			{ 0x3ff00000ffffffffL, 0x3ff0000000000001L }, { 0x4000000000000000L, 0x3ff0000000000000L },
			{ 0x4000000000000001L, 0x3ff0000000000000L }, { 0x3fffffffffffffffL, 0x3ff0000000000000L },
			{ 0x4008000000000000L, 0xc010000000000000L }, { 0xc014000000000000L, 0x4028000000000000L },
			{ CANONICAL_NAN, 0x7ff0000000000000L }, { 0xfff0000000000000L, CANONICAL_NAN },
			{ 0x7ff0000000000001L, 0x3ff0000000000000L }, { 0xfff8000000000001L, 0L } };

	static long state;

	static long next() {
		state += 0x9E3779B97F4A7C15L;
		long z = state;
		z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
		z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
		return z ^ (z >>> 31);
	}

	static final long[] PICK = { 0L, 0x8000000000000000L, CANONICAL_NAN, 0x7ff0000000000000L,
			0xfff0000000000000L, 0x3ff0000000000000L, 0xbff0000000000000L, 1L, 0x8000000000000001L };

	// gen.draw of strictmath_test.go for the kinds bits, logu and pick.
	record Gen(String kind, long a, long b, long sign) {
		long draw() {
			switch (kind) {
			case "bits":
				return next();
			case "logu": {
				final long r1 = next(), r2 = next();
				final long e = a + Long.remainderUnsigned(r1, b - a + 1);
				final long signBit = sign > 0 ? 0 : sign < 0 ? 1L << 63 : (r2 >>> 63) << 63;
				return signBit | (e + 1023) << 52 | r2 & ((1L << 52) - 1);
			}
			case "pick": {
				final long r1 = next();
				if (Long.remainderUnsigned(r1, 4) == 0)
					return PICK[(int) Long.remainderUnsigned(r1 >>> 8, PICK.length)];
				return next();
			}
			}
			throw new IllegalArgumentException(kind);
		}

		String go() {
			return "gen{\"" + kind + "\", " + a + ", " + b + ", " + sign + "}";
		}
	}

	static long canon(double x) {
		return x != x ? CANONICAL_NAN : Double.doubleToRawLongBits(x);
	}

	static long hypot(long a, long b) {
		final double x = Double.longBitsToDouble(a), y = Double.longBitsToDouble(b);
		final long strict = canon(StrictMath.hypot(x, y));
		if (canon(Math.hypot(x, y)) != strict)
			throw new IllegalStateException("Math.hypot differs from StrictMath.hypot for " + x + ", " + y);
		return strict;
	}

	public static void main(String[] args) throws Exception {
		final StringBuilder sb = new StringBuilder();
		sb.append("// SPDX-License-Identifier: MIT\n// Provenance: original\n\n");
		sb.append("// Code generated by testdata/HypotCases.java from " + System.getProperty("java.vendor") + " Java "
				+ System.getProperty("java.runtime.version") + " StrictMath results; DO NOT EDIT.\n\n");
		sb.append("package jmath\n\nfunc init() {\n\tbinaryCases[\"hypot\"] = []uint64{\n");
		final List<long[]> pairs = new ArrayList<>();
		for (long a : SPECIALS)
			for (long b : SPECIALS)
				pairs.add(new long[] { a, b });
		for (long[] p : PAIRS)
			pairs.add(p);
		for (long[] p : pairs)
			sb.append(String.format("\t\t0x%016x, 0x%016x, 0x%016x,\n", p[0], p[1], hypot(p[0], p[1])));
		sb.append("\t}\n\tbulkSpecs = append(bulkSpecs,\n");
		final Gen[][] gens = { { new Gen("bits", 0, 0, 0), new Gen("bits", 0, 0, 0) },
				{ new Gen("pick", 0, 0, 0), new Gen("pick", 0, 0, 0) },
				{ new Gen("logu", -1023, 1023, 0), new Gen("logu", -1023, 1023, 0) },
				{ new Gen("logu", -3, 3, 0), new Gen("logu", -3, 3, 0) },
				{ new Gen("logu", 0, 0, 0), new Gen("logu", 0, 1, 0) },
				{ new Gen("logu", 480, 1023, 0), new Gen("logu", 420, 1023, 0) },
				{ new Gen("logu", -1023, -480, 0), new Gen("logu", -1023, -420, 0) } };
		long seed = 0x6879706f74L;
		for (Gen[] g : gens) {
			final int n = 1 << 20;
			state = seed;
			final MessageDigest sha = MessageDigest.getInstance("SHA-256");
			final ByteBuffer buf = ByteBuffer.allocate(8).order(ByteOrder.LITTLE_ENDIAN);
			for (int i = 0; i < n; i++) {
				final long a = g[0].draw();
				final long b = g[1].draw();
				buf.clear();
				buf.putLong(hypot(a, b));
				sha.update(buf.array());
			}
			sb.append(String.format("\t\tbulkSpec{\"hypot\", %s, %s, %d, 0x%016x, \"%s\"},\n", g[0].go(), g[1].go(), n,
					seed, HexFormat.of().formatHex(sha.digest())));
			seed += 0x9E3779B97F4A7C15L;
		}
		sb.append("\t)\n}\n");
		System.out.print(sb);
	}
}
